11	// AscendC AttentionSoftmaxWithSoftcappingAndDropout kernel
12	// Computes: softmax(tanh(x / 30.0) * 30.0, dim=-1)
13	// Supports float32, float16, bfloat16
14	// Strategies: single_row (N <= 8192), splitd (N > 8192)
15	
16	#include "kernel_operator.h"
17	
18	constexpr int32_t BUFFER_NUM = 2;
19	constexpr int32_t BLOCK_M = 64;
20	constexpr int32_t BLOCK_N = 1024;
21	constexpr int32_t NUM_PHYSICAL_CORES = 20;
22	constexpr float SOFTCAP = 30.0f;
23	constexpr float INV_SOFTCAP = 1.0f / 30.0f;
24	
25	// ---------------------------------------------------------------------------
26	// Inline helpers
27	// ---------------------------------------------------------------------------
28	
29	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
30	{
31	    if (b == 0U) { return 0U; }
32	    return (a + b - 1U) / b;
33	}
34	
35	template <typename T>
36	__aicore__ inline void LoadGmToUb(
37	    AscendC::LocalTensor<T> &dst,
38	    AscendC::GlobalTensor<T> src,
39	    uint32_t count)
40	{
41	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
42	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
43	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
44	}
45	
46	template <typename T>
47	__aicore__ inline void StoreUbToGm(
48	    AscendC::GlobalTensor<T> dst,
49	    AscendC::LocalTensor<T> &src,
50	    uint32_t count)
51	{
52	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
53	    AscendC::DataCopyPad(dst, src, copyParams);
54	}
55	
56	template <typename dataType>
57	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
58	{
59	    if constexpr (std::is_same_v<dataType, bfloat16_t>) {
60	        return AscendC::RoundMode::CAST_ROUND;
61	    }
62	    return AscendC::RoundMode::CAST_NONE;
63	}
64	
65	template <typename dataType>
66	__aicore__ inline void PrepareInputFloat32(
67	    AscendC::LocalTensor<float> &dst,
68	    AscendC::LocalTensor<dataType> &src,
69	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
70	    int32_t count)
71	{
72	    if constexpr (std::is_same_v<dataType, float>) {
73	        dst = src.template ReinterpretCast<float>();
74	    } else {
75	        dst = castBuf.Get<float>();
76	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
77	        AscendC::PipeBarrier<PIPE_V>();
78	    }
79	}
80	
81	template <typename dataType>
82	__aicore__ inline void PrepareOutputFloat32(
83	    AscendC::LocalTensor<float> &dst,
84	    AscendC::LocalTensor<dataType> &out,
85	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
86	{
87	    if constexpr (std::is_same_v<dataType, float>) {
88	        dst = out.template ReinterpretCast<float>();
89	    } else {
90	        dst = castBuf.Get<float>();
91	    }
92	}
93	
94	template <typename dataType>
95	__aicore__ inline void FinalizeOutput(
96	    AscendC::LocalTensor<dataType> &out,
97	    AscendC::LocalTensor<float> &src,
98	    int32_t count)
99	{
100	    if constexpr (!std::is_same_v<dataType, float>) {
101	        AscendC::Cast(out, src, OutputRoundModeHelper<dataType>(), count);
102	        AscendC::PipeBarrier<PIPE_V>();
103	    }
104	}
105	
106	// ---------------------------------------------------------------------------
107	// Single-Row Kernel: N <= 8192 — full row fits in UB
108	// ---------------------------------------------------------------------------
109	
110	template <typename dataType>
111	class AttnSoftmaxSoftcappingKernel {
112	public:
113	    __aicore__ inline void Init(
114	        GM_ADDR x, GM_ADDR y,
115	        int32_t M, int32_t N, int32_t usedCoreNum, int32_t tasksPerCore)
116	    {
117	        this->M = M;
118	        this->N = N;
119	        this->usedCoreNum = usedCoreNum;
120	        this->tasksPerCore = tasksPerCore;
121	
122	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
123	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
124	
125	        if ASCEND_IS_AIV {
126	            subBlockRows_ = BLOCK_M / AscendC::GetSubBlockNum();
127	
128	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, N * sizeof(dataType));
129	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
130	            pipe.InitBuffer(reduceBuf_, 2 * N * sizeof(uint8_t));
131	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
132	            pipe.InitBuffer(tmpBuf_, N * sizeof(float));
133	            if constexpr (!std::is_same_v<dataType, float>) {
134	                pipe.InitBuffer(xCastBuf_, N * sizeof(float));
135	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
136	            }
137	        }
138	    }
139	
140	    __aicore__ inline void Process()
141	    {
142	        if ASCEND_IS_AIV {
143	            const int coreIdx = AscendC::GetBlockIdx();
144	            const int subBlockIdx = AscendC::GetSubBlockIdx();
145	
146	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
147	                const int bx = coreIdx * tasksPerCore + localIdx;
148	                const int mNum = (M + BLOCK_M - 1) / BLOCK_M;
149	                if (bx >= mNum) {
150	                    continue;
151	                }
152	
153	                for (int row = 0; row < subBlockRows_; ++row) {
154	                    const int rowIdx = bx * BLOCK_M + subBlockIdx * subBlockRows_ + row;
155	                    if (rowIdx < M) {
156	                        ProcessRow(rowIdx);
157	                    }
158	                }
159	            }
160	        }
161	    }
162	
163	private:
164	    __aicore__ inline void CopyIn(int32_t rowIdx)
165	    {
166	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
167	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
168	        xInQueue_.EnQue(xInLocal_);
169	    }
170	
171	    __aicore__ inline void CopyOut(int32_t rowIdx)
172	    {
173	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
174	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
175	        yOutQueue_.FreeTensor(yOutLocal_);
176	    }
177	
178	    __aicore__ inline void Compute()
179	    {
180	        // Allocate output
181	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
182	        PrepareOutputFloat32<dataType>(yLocal_, yOutLocal_, yCastBuf_);
183	
184	        // Deque input and prepare float32 working buffer
185	        xInLocal_ = xInQueue_.DeQue<dataType>();
186	        PrepareInputFloat32<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
187	        tmpLocal_ = tmpBuf_.Get<float>();
188	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
189	        sumLocal_ = sumBuf_.Get<float>();
190	
191	        // === Step 1: Softcapping — tanh(x / 30.0) * 30.0 ===
192	        // scale down: x = x * (1/30)
193	        AscendC::Muls(xLocal_, xLocal_, INV_SOFTCAP, N);
194	
195	        // tanh(x) via exp formula: tanh(x) = (exp(2x) - 1) / (exp(2x) + 1)
196	        // tmp = 2*x
197	        AscendC::Muls(tmpLocal_, xLocal_, 2.0f, N);
198	        // tmp = exp(2x)
199	        AscendC::Exp(tmpLocal_, tmpLocal_, N);
200	        // x = exp(2x) - 1
201	        AscendC::Adds(xLocal_, tmpLocal_, -1.0f, N);
202	        // tmp = exp(2x) + 1
203	        AscendC::Adds(tmpLocal_, tmpLocal_, 1.0f, N);
204	        // x = (exp(2x)-1) / (exp(2x)+1) = tanh(x)
205	        AscendC::Div(xLocal_, xLocal_, tmpLocal_, N);
206	
207	        // scale back: x = x * 30.0
208	        AscendC::Muls(xLocal_, xLocal_, SOFTCAP, N);
209	
210	        // === Step 2: Softmax along last dim ===
211	        // Step 2a: Find max for numerical stability
212	        AscendC::ReduceMax<float>(sumLocal_, xLocal_, reduceTmpLocal_, N);
213	
214	        float maxVal = sumLocal_.GetValue(0);
215	
216	        // Step 2b: Subtract max
217	        AscendC::Adds(xLocal_, xLocal_, -maxVal, N);
218	
219	        // Step 2c: Compute exp
220	        AscendC::Exp(xLocal_, xLocal_, N);
221	
222	        // Step 2d: Compute sum of exp
223	        AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceTmpLocal_, N);
224	
225	        float sumVal = sumLocal_.GetValue(0);
226	
227	        // Step 2e: Divide by sum (use tmp as scratch for scalar->buffer)
228	        AscendC::Duplicate(tmpLocal_, sumVal, 1);
229	        // Compute 1/sum for better numerical stability
230	        AscendC::Reciprocal(tmpLocal_, tmpLocal_, 1);
231	        float invSum = tmpLocal_.GetValue(0);
232	        AscendC::Muls(xLocal_, xLocal_, invSum, N);
233	
234	        // === Step 3: Cast back to output dtype and finalize ===
235	        FinalizeOutput<dataType>(yOutLocal_, xLocal_, N);
236	
237	        // Free input, enque output
238	        xInQueue_.FreeTensor(xInLocal_);
239	        yOutQueue_.EnQue(yOutLocal_);
240	    }
241	
242	    __aicore__ inline void ProcessRow(int32_t rowIdx)
243	    {
244	        CopyIn(rowIdx);
245	        Compute();
246	        CopyOut(rowIdx);
247	    }
248	
249	private:
250	    int32_t M = 0;
251	    int32_t N = 0;
252	    int32_t usedCoreNum = 0;
253	    int32_t tasksPerCore = 0;
254	    int subBlockRows_ = 0;
255	
256	    AscendC::TPipe pipe;
257	    AscendC::GlobalTensor<dataType> xGM_;
258	    AscendC::GlobalTensor<dataType> yGM_;
259	
260	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
261	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
262	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
263	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
264	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
265	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
266	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
267	
268	    AscendC::LocalTensor<dataType> xInLocal_;
269	    AscendC::LocalTensor<dataType> yOutLocal_;
270	    AscendC::LocalTensor<float> xLocal_;
271	    AscendC::LocalTensor<float> yLocal_;
272	    AscendC::LocalTensor<float> tmpLocal_;
273	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
274	    AscendC::LocalTensor<float> sumLocal_;
275	};
276	
277	// ---------------------------------------------------------------------------
278	// Split-D Kernel: N > 8192 — row split along N dimension
279	// ---------------------------------------------------------------------------
280	
281	template <typename dataType>
282	class AttnSoftmaxSoftcappingSplitDKernel {
283	public:
284	    __aicore__ inline void Init(
285	        GM_ADDR x, GM_ADDR y,
286	        int32_t M, int32_t N, int32_t usedCoreNum, int32_t tasksPerCore)
287	    {
288	        this->M = M;
289	        this->N = N;
290	        this->usedCoreNum = usedCoreNum;
291	        this->tasksPerCore = tasksPerCore;
292	
293	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
294	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
295	
296	        if ASCEND_IS_AIV {
297	            subBlockRows_ = BLOCK_M / AscendC::GetSubBlockNum();
298	
299	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, BLOCK_N * sizeof(dataType));
300	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, BLOCK_N * sizeof(dataType));
301	            pipe.InitBuffer(reduceBuf_, 2 * BLOCK_N * sizeof(uint8_t));
302	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
303	            pipe.InitBuffer(tmpBuf_, BLOCK_N * sizeof(float));
304	            pipe.InitBuffer(accBuf_, BLOCK_N * sizeof(float));
305	            if constexpr (!std::is_same_v<dataType, float>) {
306	                pipe.InitBuffer(xCastBuf_, BLOCK_N * sizeof(float));
307	                pipe.InitBuffer(yCastBuf_, BLOCK_N * sizeof(float));
308	            }
309	        }
310	    }
311	
312	    __aicore__ inline void Process()
313	    {
314	        if ASCEND_IS_AIV {
315	            const int coreIdx = AscendC::GetBlockIdx();
316	            const int subBlockIdx = AscendC::GetSubBlockIdx();
317	
318	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
319	                const int bx = coreIdx * tasksPerCore + localIdx;
320	                const int mNum = (M + BLOCK_M - 1) / BLOCK_M;
321	                if (bx >= mNum) {
322	                    continue;
323	                }
324	
325	                for (int row = 0; row < subBlockRows_; ++row) {
326	                    const int rowIdx = bx * BLOCK_M + subBlockIdx * subBlockRows_ + row;
327	                    if (rowIdx < M) {
328	                        ProcessRow(rowIdx);
329	                    }
330	                }
331	            }
332	        }
333	    }
334	
335	private:
336	    __aicore__ inline int32_t NumTiles() const
337	    {
338	        return (N + BLOCK_N - 1) / BLOCK_N;
339	    }
340	
341	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
342	    {
343	        return (colBase + BLOCK_N <= N) ? BLOCK_N : (N - colBase);
344	    }
345	
346	    __aicore__ inline void CopyIn(int32_t rowIdx, int32_t colBase, int32_t validN)
347	    {
348	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
349	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
350	                   static_cast<uint32_t>(validN));
351	        xInQueue_.EnQue(xInLocal_);
352	    }
353	
354	    __aicore__ inline void CopyOut(int32_t rowIdx, int32_t colBase, int32_t validN)
355	    {
356	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
357	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_,
358	                    static_cast<uint32_t>(validN));
359	        yOutQueue_.FreeTensor(yOutLocal_);
360	    }
361	
362	    // Compute softcapping on a tile, return tile's max
363	    __aicore__ inline float ComputeSoftcappingTile(int32_t validN)
364	    {
365	        xInLocal_ = xInQueue_.DeQue<dataType>();
366	        PrepareInputFloat32<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
367	        tmpLocal_ = tmpBuf_.Get<float>();
368	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
369	
370	        // Scale down: x = x * (1/30)
371	        AscendC::Muls(xLocal_, xLocal_, INV_SOFTCAP, validN);
372	
373	        // tanh(x) = (exp(2x) - 1) / (exp(2x) + 1)
374	        AscendC::Muls(tmpLocal_, xLocal_, 2.0f, validN);
375	        AscendC::Exp(tmpLocal_, tmpLocal_, validN);
376	        AscendC::Adds(xLocal_, tmpLocal_, -1.0f, validN);
377	        AscendC::Adds(tmpLocal_, tmpLocal_, 1.0f, validN);
378	        AscendC::Div(xLocal_, xLocal_, tmpLocal_, validN);
379	
380	        // Scale back: x = x * 30.0
381	        AscendC::Muls(xLocal_, xLocal_, SOFTCAP, validN);
382	
383	        // Find max in this tile
384	        AscendC::ReduceMax<float>(sumLocal_, xLocal_, reduceTmpLocal_, validN);
385	        float tileMax = sumLocal_.GetValue(0);
386	        xInQueue_.FreeTensor(xInLocal_);
387	        return tileMax;
388	    }
389	
390	    // Pass 1: find global max over all tiles
391	    __aicore__ inline float FindGlobalMax(int32_t rowIdx)
392	    {
393	        float globalMax = -3.402823466e+38f;
394	        const int nTiles = NumTiles();
395	
396	        for (int by = 0; by < nTiles; ++by) {
397	            const int colBase = by * BLOCK_N;
398	            const int validN = GetValidN(colBase);
399	            CopyIn(rowIdx, colBase, validN);
400	            float tileMax = ComputeSoftcappingTile(validN);
401	            if (tileMax > globalMax) {
402	                globalMax = tileMax;
403	            }
404	        }
405	        return globalMax;
406	    }
407	
408	    // Pass 2: compute global sum of exp(x - max) over all tiles
409	    __aicore__ inline float ComputeGlobalSum(int32_t rowIdx, float globalMax)
410	    {
411	        float globalSum = 0.0f;
412	        const int nTiles = NumTiles();
413	
414	        for (int by = 0; by < nTiles; ++by) {
415	            const int colBase = by * BLOCK_N;
416	            const int validN = GetValidN(colBase);
417	            CopyIn(rowIdx, colBase, validN);
418	
419	            xInLocal_ = xInQueue_.DeQue<dataType>();
420	            PrepareInputFloat32<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
421	            tmpLocal_ = tmpBuf_.Get<float>();
422	            reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
423	
424	            // Softcapping again
425	            AscendC::Muls(xLocal_, xLocal_, INV_SOFTCAP, validN);
426	            AscendC::Muls(tmpLocal_, xLocal_, 2.0f, validN);
427	            AscendC::Exp(tmpLocal_, tmpLocal_, validN);
428	            AscendC::Adds(xLocal_, tmpLocal_, -1.0f, validN);
429	            AscendC::Adds(tmpLocal_, tmpLocal_, 1.0f, validN);
430	            AscendC::Div(xLocal_, xLocal_, tmpLocal_, validN);
431	            AscendC::Muls(xLocal_, xLocal_, SOFTCAP, validN);
432	
433	            // Subtract max, exp, accumulate sum
434	            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
435	            AscendC::Exp(xLocal_, xLocal_, validN);
436	            AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceTmpLocal_, validN);
437	            globalSum += sumLocal_.GetValue(0);
438	
439	            xInQueue_.FreeTensor(xInLocal_);
440	        }
441	        return globalSum;
442	    }
443	
444	    // Pass 3: normalize each tile and write output
445	    __aicore__ inline void NormalizeAndWrite(int32_t rowIdx, float globalMax, float invGlobalSum)
446	    {
447	        const int nTiles = NumTiles();
448	
449	        for (int by = 0; by < nTiles; ++by) {
450	            const int colBase = by * BLOCK_N;
451	            const int validN = GetValidN(colBase);
452	            CopyIn(rowIdx, colBase, validN);
453	
454	            // Deque input
455	            xInLocal_ = xInQueue_.DeQue<dataType>();
456	            PrepareInputFloat32<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
457	            tmpLocal_ = tmpBuf_.Get<float>();
458	
459	            // Softcapping
460	            AscendC::Muls(xLocal_, xLocal_, INV_SOFTCAP, validN);
461	            AscendC::Muls(tmpLocal_, xLocal_, 2.0f, validN);
462	            AscendC::Exp(tmpLocal_, tmpLocal_, validN);
463	            AscendC::Adds(xLocal_, tmpLocal_, -1.0f, validN);
464	            AscendC::Adds(tmpLocal_, tmpLocal_, 1.0f, validN);
465	            AscendC::Div(xLocal_, xLocal_, tmpLocal_, validN);
466	            AscendC::Muls(xLocal_, xLocal_, SOFTCAP, validN);
467	
468	            // Subtract max, exp, normalize
469	            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
470	            AscendC::Exp(xLocal_, xLocal_, validN);
471	            AscendC::Muls(xLocal_, xLocal_, invGlobalSum, validN);
472	
473	            // Allocate output, cast, enque
474	            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
475	            PrepareOutputFloat32<dataType>(yLocal_, yOutLocal_, yCastBuf_);
476	            FinalizeOutput<dataType>(yOutLocal_, xLocal_, validN);
477	
478	            xInQueue_.FreeTensor(xInLocal_);
479	            yOutQueue_.EnQue(yOutLocal_);
480	
481	            CopyOut(rowIdx, colBase, validN);
482	        }
483	    }
484	
485	    __aicore__ inline void ProcessRow(int32_t rowIdx)
486	    {
487	        float globalMax = FindGlobalMax(rowIdx);
488	        float globalSum = ComputeGlobalSum(rowIdx, globalMax);
489	        float invGlobalSum = 1.0f / globalSum;
490	        NormalizeAndWrite(rowIdx, globalMax, invGlobalSum);
491	    }
492	
493	private:
494	    int32_t M = 0;
495	    int32_t N = 0;
496	    int32_t usedCoreNum = 0;
497	    int32_t tasksPerCore = 0;
498	    int subBlockRows_ = 0;
499	
500	    AscendC::TPipe pipe;
501	    AscendC::GlobalTensor<dataType> xGM_;
502	    AscendC::GlobalTensor<dataType> yGM_;
503	
504	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
505	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
506	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
507	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
508	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
509	    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
510	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
511	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
512	
513	    AscendC::LocalTensor<dataType> xInLocal_;
514	    AscendC::LocalTensor<dataType> yOutLocal_;
515	    AscendC::LocalTensor<float> xLocal_;
516	    AscendC::LocalTensor<float> yLocal_;
517	    AscendC::LocalTensor<float> tmpLocal_;
518	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
519	    AscendC::LocalTensor<float> sumLocal_;
520	};
521	
522	// =========================================================================
523	// Shared dtype-dispatch helper
524	// =========================================================================
525	
526	template <template <typename> class Kernel, typename... ExtraArgs>
527	__aicore__ inline void DispatchAttnSoftmaxSoftcapping(
528	    GM_ADDR x, GM_ADDR y,
529	    int32_t M, int32_t N, int32_t usedCoreNum, int32_t tasksPerCore,
530	    int64_t dtypeFlag, ExtraArgs... extraArgs)
531	{
532	    if (dtypeFlag == 0) {
533	        Kernel<float> kernel;
534	        kernel.Init(x, y, M, N, usedCoreNum, tasksPerCore, extraArgs...);
535	        kernel.Process();
536	    } else if (dtypeFlag == 1) {
537	        Kernel<half> kernel;
538	        kernel.Init(x, y, M, N, usedCoreNum, tasksPerCore, extraArgs...);
539	        kernel.Process();
540	    } else {
541	        Kernel<bfloat16_t> kernel;
542	        kernel.Init(x, y, M, N, usedCoreNum, tasksPerCore, extraArgs...);
543	        kernel.Process();
544	    }
545	}
546	
547	// =========================================================================
548	// Kernel entry points
549	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
550	// =========================================================================
551	
552	extern "C" __global__ __aicore__ void attention_softmax_softcapping_dropout_single_row(
553	    GM_ADDR x, GM_ADDR y,
554	    int32_t M, int32_t N, int32_t usedCoreNum, int32_t tasksPerCore,
555	    int64_t dtypeFlag)
556	{
557	    DispatchAttnSoftmaxSoftcapping<AttnSoftmaxSoftcappingKernel>(
558	        x, y, M, N, usedCoreNum, tasksPerCore, dtypeFlag);
559	}
560	
561	extern "C" __global__ __aicore__ void attention_softmax_softcapping_dropout_splitd(
562	    GM_ADDR x, GM_ADDR y,
563	    int32_t M, int32_t N, int32_t usedCoreNum, int32_t tasksPerCore,
564	    int64_t dtypeFlag)
565	{
566	    DispatchAttnSoftmaxSoftcapping<AttnSoftmaxSoftcappingSplitDKernel>(
567	        x, y, M, N, usedCoreNum, tasksPerCore, dtypeFlag);
568	}
