13	// ============================================================
14	// 行处理算子 op_host 模板
15	// 适用: LayerNorm, Softmax, BatchNorm 等按行/维度归约算子
16	// 使用: 复制到 csrc/ops/<op_name>/op_host/<op_name>.cpp，
17	//       替换 <op_name>/<OpName> 占位符，修改参数和 tiling 逻辑
18	// ============================================================
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	#include "aclrtlaunch_<op_name>.h"
23	
24	namespace ascend_kernel {
25	
26	at::Tensor <op_name>(const at::Tensor &self /* , 其他输入参数 */)
27	{
28	    // ---- 输入校验 ----
29	    TORCH_CHECK(self.dim() > 0, "<op_name>: input must have at least 1 dimension");
30	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat,
31	                "<op_name>: only float16 and float32 are supported, got ", self.scalar_type());
32	
33	    // ---- 计算行维度 ----
34	    // 将 tensor 视为 [totalRows, dimLength]
35	    int64_t dimLength = self.size(-1);    // <-- 根据算子语义调整
36	    if (dimLength == 0) {
37	        return at::empty_like(self);
38	    }
39	    int64_t totalRows = self.numel() / dimLength;
40	
41	    if (totalRows == 0) {
42	        return at::empty_like(self);
43	    }
44	
45	    at::Tensor x = self.contiguous();
46	    int64_t dtypeSize = x.element_size();
47	    if (dtypeSize == 0) { dtypeSize = 1; }
48	
49	    // ---- 获取硬件参数 ----
50	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
51	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
52	    uint64_t ubSize;
53	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
54	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
55	
56	    // ---- 对齐 ----
57	    int64_t alignElements = 32 / dtypeSize;
58	    int64_t dimLengthAlign = ((dimLength + alignElements - 1) / alignElements) * alignElements;
59	
60	    // ---- UB 容量检查 ----
61	    // bufferCoefficient = 每元素在 UB 中总占用字节, 从设计文档 UB 分配表推导
62	    // 示例: inQ*4 + outQ*4 + tmpBuf*4 = 12 (fp16 with fp32 compute)
63	    int64_t bufferCoefficient = (dtypeSize == 2) ? 12 : 16; // <-- 根据实际修改
64	    int64_t maxDimLength = ubSizeLimit / bufferCoefficient;
65	    maxDimLength = (maxDimLength / alignElements) * alignElements;
66	    TORCH_CHECK(dimLengthAlign <= maxDimLength,
67	                "<op_name>: dimLength ", dimLength, " exceeds UB capacity (max ", maxDimLength, ")");
68	
69	    // ---- Padding ----
70	    at::Tensor kernelInput;
71	    if (dimLength != dimLengthAlign) {
72	        kernelInput = x.reshape({totalRows, dimLength});
73	        kernelInput = at::constant_pad_nd(kernelInput, {0, dimLengthAlign - dimLength}, 0.0);
74	        kernelInput = kernelInput.contiguous();
75	    } else {
76	        kernelInput = x.reshape({totalRows, dimLengthAlign}).contiguous();
77	    }
78	    at::Tensor kernelOutput = at::empty_like(kernelInput);
79	
80	    // ---- Block 级 tiling (按行分配) ----
81	    int64_t usedCoreNum = std::max(int64_t(1), std::min(totalRows, coreNum));
82	    TORCH_CHECK(usedCoreNum != 0, "usedCoreNum should not be 0");
83	    int64_t formerLength = (totalRows + usedCoreNum - 1) / usedCoreNum;
84	    int64_t tailLength = formerLength - 1;
85	    int64_t formerNum = totalRows - tailLength * usedCoreNum;
86	
87	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
88	
89	    EXEC_KERNEL_CMD(<op_name>, blockDim,
90	                    kernelInput, kernelOutput,
91	                    totalRows, dimLength, dimLengthAlign,
92	                    formerNum, formerLength, tailLength
93	                    /* , 其他算子特有参数 */);
94	
95	    // ---- 去 padding + reshape ----
96	    at::Tensor output = kernelOutput;
97	    if (dimLength != dimLengthAlign) {
98	        output = output.narrow(-1, 0, dimLength).contiguous();
99	    }
100	    output = output.reshape(self.sizes());
101	
102	    return output;
103	}
104	
105	}  // namespace ascend_kernel
