#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_adaptive_instance_norm2d_backward.h"

namespace ascend_kernel {

std::tuple<at::Tensor, at::Tensor, at::Tensor> adaptive_instance_norm2d_backward(
    const at::Tensor &grad_output,
    const at::Tensor &x,
    const at::Tensor &weight,
    const at::Tensor &mean,
    const at::Tensor &std) {
    // ---- Input validation ----
    TORCH_CHECK(grad_output.dim() == 4, "grad_output must be 4D (N,C,H,W)");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(x.sizes() == grad_output.sizes(), "x and grad_output must have same shape");

    auto dtype = x.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kFloat || dtype == at::kBFloat16,
                "Only float16, float32, bfloat16 supported, got ", dtype);

    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t H = x.size(2);
    int64_t W = x.size(3);
    int64_t spatialSize = H * W;
    int64_t totalNC = N * C;

    if (totalNC == 0) {
        at::Tensor gi = at::empty_like(x);
        at::Tensor gw = at::zeros({C}, at::dtype(at::kFloat).device(x.device()));
        at::Tensor gb = at::zeros({C}, at::dtype(at::kFloat).device(x.device()));
        return std::make_tuple(gi, gw, gb);
    }

    // Ensure contiguous inputs
    at::Tensor goCont = grad_output.contiguous();
    at::Tensor xCont = x.contiguous();

    // weight: reshape from (C,) for 1D access
    at::Tensor wCont = weight.contiguous();

    // mean/std: reshape from (N,C,1,1) → (N,C) if needed
    at::Tensor meanCont;
    at::Tensor stdCont;
    if (mean.dim() == 4) {
        meanCont = mean.contiguous().view({N, C});
        stdCont = std.contiguous().view({N, C});
    } else {
        meanCont = mean.contiguous();
        stdCont = std.contiguous();
    }

    // ---- Get hardware parameters ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block-level tiling ----
    int64_t usedCoreNum = std::max(int64_t(1), std::min(totalNC, coreNum));
    int64_t tasksPerCore = (totalNC + usedCoreNum - 1) / usedCoreNum;

