    } else if (dtype == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // ---- Launch kernel ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int32_t N32 = static_cast<int32_t>(N);
    int32_t C32 = static_cast<int32_t>(C);
    int32_t H32 = static_cast<int32_t>(H);
    int32_t W32 = static_cast<int32_t>(W);
    int32_t spSize32 = static_cast<int32_t>(spatialSize);
    int32_t usedCoreNum32 = static_cast<int32_t>(usedCoreNum);
    int32_t tasksPerCore32 = static_cast<int32_t>(tasksPerCore);
    int32_t tileSpatial32 = static_cast<int32_t>(tileSpatial);

    EXEC_KERNEL_CMD(adaptive_instance_norm2d_backward, blockDim,
                    goCont, xCont, wCont, meanCont, stdCont,
                    gradInput, gradWeight, gradBias,
                    partialGW, partialGB,
                    N32, C32, H32, W32,
                    spSize32, usedCoreNum32, tasksPerCore32, tileSpatial32,
                    dtypeFlag);

    return std::make_tuple(gradInput, gradWeight, gradBias);
}

