// AscendC AdaptiveInstanceNormalization2DBackward kernel
// Computes gradients for AdaIN 2D: grad_input, grad_weight, grad_bias
// Supports float32, float16, bfloat16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// =============================================================================
// Main Kernel Class
// =============================================================================

template <typename dataType>
class AdaIN2DBackwardKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR gradOutput, GM_ADDR x, GM_ADDR weight,
        GM_ADDR mean, GM_ADDR std,
        GM_ADDR gradInput, GM_ADDR gradWeight, GM_ADDR gradBias,
        GM_ADDR partialGW, GM_ADDR partialGB,
        int32_t N, int32_t C, int32_t H, int32_t W,
        int32_t spatialSize, int32_t usedCoreNum,
        int32_t tasksPerCore, int32_t tileSpatial) {
        this->N_ = N;
        this->C_ = C;
        this->H_ = H;
        this->W_ = W;
        this->spatialSize_ = spatialSize;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        this->tileSpatial_ = tileSpatial;

        gradOutputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gradOutput),
                                       static_cast<int64_t>(N_) * C_ * H_ * W_);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
                              static_cast<int64_t>(N_) * C_ * H_ * W_);
        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), C_);
        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mean),
                                 static_cast<int64_t>(N_) * C_);
        stdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(std),
                                static_cast<int64_t>(N_) * C_);
        gradInputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gradInput),
                                      static_cast<int64_t>(N_) * C_ * H_ * W_);
        gradWeightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gradWeight), C_);
        gradBiasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gradBias), C_);
        partialGWGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(partialGW),
                                      static_cast<int64_t>(usedCoreNum_) * C_);
        partialGBGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(partialGB),
                                      static_cast<int64_t>(usedCoreNum_) * C_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(goInQueue_, BUFFER_NUM, tileSpatial_ * sizeof(dataType));
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileSpatial_ * sizeof(dataType));
            pipe.InitBuffer(giOutQueue_, BUFFER_NUM, tileSpatial_ * sizeof(dataType));
            pipe.InitBuffer(reduceBuf_, tileSpatial_ * sizeof(float));
            pipe.InitBuffer(tmpBuf_, tileSpatial_ * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(castGoBuf_, tileSpatial_ * sizeof(float));
                pipe.InitBuffer(castXBuf_, tileSpatial_ * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int32_t coreIdx = static_cast<int32_t>(AscendC::GetBlockIdx());
            const int32_t totalNC = N_ * C_;

            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int32_t bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= totalNC) { continue; }
                ProcessNCPair(bx, coreIdx);
            }

            AscendC::SyncAll();

            if (coreIdx == 0) {
                ReduceWorkspace();
            }
        }
    }

private:
    __aicore__ inline int32_t GetTileLen(int32_t sStart) const {
        int32_t rem = spatialSize_ - sStart;
        return (rem > tileSpatial_) ? tileSpatial_ : rem;
    }

    // Cast input to float32
    __aicore__ inline AscendC::LocalTensor<float> ToFp32(
        AscendC::LocalTensor<dataType> &in,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        int32_t count) {
        if constexpr (std::is_same_v<dataType, float>) {
            return in.template ReinterpretCast<float>();
        } else {
            AscendC::LocalTensor<float> out = castBuf.Get<float>();
            AscendC::Cast(out, in, AscendC::RoundMode::CAST_NONE, count);
            return out;
        }
    }

    // Load spatial tile from GM to UB
    __aicore__ inline void LoadTile(
        AscendC::LocalTensor<dataType> &dst,
        AscendC::GlobalTensor<dataType> &gm,
        int64_t baseOffset, int32_t sStart, int32_t count) {
        AscendC::DataCopyExtParams copyParams{1,
            static_cast<uint32_t>(count) * static_cast<uint32_t>(sizeof(dataType)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<dataType> padParams{true, 0, 0, static_cast<dataType>(0)};
        AscendC::DataCopyPad(dst, gm[baseOffset + sStart], copyParams, padParams);
    }

    __aicore__ inline void StoreTile(
        AscendC::GlobalTensor<dataType> &gm,
        int64_t baseOffset, int32_t sStart,
        AscendC::LocalTensor<dataType> &src, int32_t count) {
        AscendC::DataCopyExtParams copyParams{1,
            static_cast<uint32_t>(count) * static_cast<uint32_t>(sizeof(dataType)), 0, 0, 0};
        AscendC::DataCopyPad(gm[baseOffset + sStart], src, copyParams);
    }

    // Process one (N,C) pair
    __aicore__ inline void ProcessNCPair(int32_t ncIdx, int32_t coreIdx) {
        int32_t nIdx = ncIdx / C_;
        int32_t cIdx = ncIdx % C_;
        int64_t goBase = static_cast<int64_t>(nIdx) * C_ * H_ * W_
                         + static_cast<int64_t>(cIdx) * H_ * W_;

        // Get scalars (reuse sumBuf for small scalars)
        AscendC::LocalTensor<float> sBuf = sumBuf_.Get<float>();

        // weight[cIdx]
        dataType wVal = weightGM_.GetValue(cIdx);
        float wFp32 = static_cast<float>(wVal);

        // mean[nIdx, cIdx]
        int64_t meanBase = static_cast<int64_t>(nIdx) * C_ + cIdx;
        dataType mVal = meanGM_.GetValue(meanBase);
        float mFp32 = static_cast<float>(mVal);

        // std[nIdx, cIdx]
        dataType sVal = stdGM_.GetValue(meanBase);
        float sFp32 = static_cast<float>(sVal);
        float invStd = 1.0f / sFp32;

        // ---- Pass 1: accumulate reductions ----
        float accGO = 0.0f, accGW = 0.0f, accGOXC = 0.0f;
        float accGOS = 0.0f, accXC = 0.0f;

        // Get work buffer for reduces
        AscendC::LocalTensor<float> reduceLocal = reduceBuf_.Get<float>();
        AscendC::LocalTensor<float> tmpLocal = tmpBuf_.Get<float>();

        int32_t numTiles = (spatialSize_ + tileSpatial_ - 1) / tileSpatial_;
        for (int32_t st = 0; st < numTiles; ++st) {
            int32_t sStart = st * tileSpatial_;
            int32_t curLen = GetTileLen(sStart);

            // Load grad_output tile
            AscendC::LocalTensor<dataType> goLocal = goInQueue_.AllocTensor<dataType>();
            LoadTile(goLocal, gradOutputGM_, goBase, sStart, curLen);
            goInQueue_.EnQue(goLocal);

            // Load x tile
            AscendC::LocalTensor<dataType> xLocal = xInQueue_.AllocTensor<dataType>();
            LoadTile(xLocal, xGM_, goBase, sStart, curLen);
            xInQueue_.EnQue(xLocal);

            // Deque data
            goLocal = goInQueue_.DeQue<dataType>();
            xLocal = xInQueue_.DeQue<dataType>();

            // Cast to float32
            AscendC::LocalTensor<float> goFp32 = ToFp32(goLocal, castGoBuf_, curLen);
            AscendC::LocalTensor<float> xFp32 = ToFp32(xLocal, castXBuf_, curLen);

            // xc = x - mean
            AscendC::Adds(xFp32, xFp32, -mFp32, curLen);

            // 1. acc_go += sum(go)
            AscendC::ReduceSum(sBuf, goFp32, reduceLocal, curLen);
            accGO += sBuf.GetValue(0);

            // 2. xn = xc * inv_std,  go_xn = go * xn,  acc_gw += sum(go_xn)
            AscendC::Muls(tmpLocal, xFp32, invStd, curLen);
            AscendC::Mul(tmpLocal, goFp32, tmpLocal, curLen);
            AscendC::ReduceSum(sBuf, tmpLocal, reduceLocal, curLen);
            accGW += sBuf.GetValue(0);

            // 3. gos = go * w,  gos_xc = gos * xc,  acc_goxc += sum(gos_xc)
            AscendC::Muls(tmpLocal, goFp32, wFp32, curLen);    // tmp = gos
            AscendC::Mul(tmpLocal, tmpLocal, xFp32, curLen);    // tmp = gos * xc
            AscendC::ReduceSum(sBuf, tmpLocal, reduceLocal, curLen);
            accGOXC += sBuf.GetValue(0);

            // 4. gos = go * w,  acc_gos += sum(gos)
            AscendC::Muls(tmpLocal, goFp32, wFp32, curLen);
            AscendC::ReduceSum(sBuf, tmpLocal, reduceLocal, curLen);
            accGOS += sBuf.GetValue(0);

            // 5. acc_xc += sum(xc)
            AscendC::ReduceSum(sBuf, xFp32, reduceLocal, curLen);
            accXC += sBuf.GetValue(0);

            // Free input
            goInQueue_.FreeTensor(goLocal);
            xInQueue_.FreeTensor(xLocal);
        }

        // ---- Compute intermediate scalars ----
        float sSq = sFp32 * sFp32;
        float sCubed = sSq * sFp32;
        float invSCubed = 1.0f / sCubed;
        float gradVar = accGOXC * (-0.5f) * invSCubed;

        float invSpSize = 1.0f / static_cast<float>(spatialSize_);
        float xcMean = accXC * invSpSize;
        float gradMean = accGOS * (-invStd) + gradVar * (-2.0f) * xcMean;

        float coefXC = gradVar * 2.0f * invSpSize;
        float constOff = gradMean * invSpSize;

        // ---- Pass 2: compute grad_input ----
        for (int32_t st = 0; st < numTiles; ++st) {
            int32_t sStart = st * tileSpatial_;
            int32_t curLen = GetTileLen(sStart);

            // Load grad_output
            AscendC::LocalTensor<dataType> goLocal = goInQueue_.AllocTensor<dataType>();
            LoadTile(goLocal, gradOutputGM_, goBase, sStart, curLen);
            goInQueue_.EnQue(goLocal);

            // Load x
            AscendC::LocalTensor<dataType> xLocal = xInQueue_.AllocTensor<dataType>();
            LoadTile(xLocal, xGM_, goBase, sStart, curLen);
            xInQueue_.EnQue(xLocal);

            // Deque
            goLocal = goInQueue_.DeQue<dataType>();
            xLocal = xInQueue_.DeQue<dataType>();

            // Cast to float32
            AscendC::LocalTensor<float> goFp32 = ToFp32(goLocal, castGoBuf_, curLen);
            AscendC::LocalTensor<float> xFp32 = ToFp32(xLocal, castXBuf_, curLen);

            // xc = x - mean
            AscendC::Adds(xFp32, xFp32, -mFp32, curLen);

            // gos = go * weight[c]
            AscendC::Muls(goFp32, goFp32, wFp32, curLen);

            // gi = gos * inv_std + coef_xc * xc + const_offset
            // Step 1: gi = gos * inv_std
            AscendC::Muls(goFp32, goFp32, invStd, curLen);
            // Step 2: gi += coef_xc * xc (use Axpy = y = a*x + y)
            AscendC::Axpy(goFp32, xFp32, coefXC, curLen);
            // Step 3: gi += const_offset
            AscendC::Adds(goFp32, goFp32, constOff, curLen);

            // Free inputs
            goInQueue_.FreeTensor(goLocal);
            xInQueue_.FreeTensor(xLocal);

            // Alloc output, cast back to dtype
            AscendC::LocalTensor<dataType> giLocal = giOutQueue_.AllocTensor<dataType>();
            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::DataCopy(giLocal, goFp32, curLen);
            } else {
                AscendC::Cast(giLocal, goFp32, AscendC::RoundMode::CAST_NONE, curLen);
            }
            giOutQueue_.EnQue(giLocal);

            // Write to output
            giLocal = giOutQueue_.DeQue<dataType>();
            StoreTile(gradInputGM_, goBase, sStart, giLocal, curLen);
            giOutQueue_.FreeTensor(giLocal);
        }

        // Write partial sums to workspace
        int64_t wsIdx = static_cast<int64_t>(coreIdx) * C_ + cIdx;
        partialGWGM_.SetValue(wsIdx, accGW);
        partialGBGM_.SetValue(wsIdx, accGO);
    }

    // Phase 2: Core 0 reduces workspace
    __aicore__ inline void ReduceWorkspace() {
        for (int32_t c = 0; c < C_; ++c) {
            float gW = 0.0f;
            float gB = 0.0f;
            for (int32_t i = 0; i < usedCoreNum_; ++i) {
                int64_t wsIdx = static_cast<int64_t>(i) * C_ + c;
                gW += partialGWGM_.GetValue(wsIdx);
                gB += partialGBGM_.GetValue(wsIdx);
            }
            gradWeightGM_.SetValue(c, gW);
            gradBiasGM_.SetValue(c, gB);
        }
    }

private:
    int32_t N_ = 0, C_ = 0, H_ = 0, W_ = 0;
    int32_t spatialSize_ = 0, usedCoreNum_ = 0, tasksPerCore_ = 0, tileSpatial_ = 0;

    AscendC::TPipe pipe;

    AscendC::GlobalTensor<dataType> gradOutputGM_;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> weightGM_;
    AscendC::GlobalTensor<dataType> meanGM_;
    AscendC::GlobalTensor<dataType> stdGM_;
    AscendC::GlobalTensor<dataType> gradInputGM_;
    AscendC::GlobalTensor<float> gradWeightGM_;
    AscendC::GlobalTensor<float> gradBiasGM_;
    AscendC::GlobalTensor<float> partialGWGM_;
    AscendC::GlobalTensor<float> partialGBGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> goInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> giOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castGoBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castXBuf_;
};

// =============================================================================
// Kernel entry point
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =============================================================================

extern "C" __global__ __aicore__ void adaptive_instance_norm2d_backward(
    GM_ADDR grad_output, GM_ADDR x, GM_ADDR weight,
    GM_ADDR mean, GM_ADDR std,
    GM_ADDR grad_input, GM_ADDR grad_weight, GM_ADDR grad_bias,
    GM_ADDR partial_gw, GM_ADDR partial_gb,
    int32_t N, int32_t C, int32_t H, int32_t W,
    int32_t spatial_size, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileSpatial,
    int64_t dtypeFlag) {
    if (dtypeFlag == 0) {
        AdaIN2DBackwardKernel<float> kernel;
        kernel.Init(grad_output, x, weight, mean, std,
                    grad_input, grad_weight, grad_bias,
                    partial_gw, partial_gb,
                    N, C, H, W,
                    spatial_size, usedCoreNum, tasksPerCore, tileSpatial);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        AdaIN2DBackwardKernel<half> kernel;
        kernel.Init(grad_output, x, weight, mean, std,
                    grad_input, grad_weight, grad_bias,
                    partial_gw, partial_gb,
                    N, C, H, W,
                    spatial_size, usedCoreNum, tasksPerCore, tileSpatial);
        kernel.Process();
    } else {
        AdaIN2DBackwardKernel<bfloat16_t> kernel;
        kernel.Init(grad_output, x, weight, mean, std,
                    grad_input, grad_weight, grad_bias,
                    partial_gw, partial_gb,
                    N, C, H, W,
                    spatial_size, usedCoreNum, tasksPerCore, tileSpatial);
        kernel.Process();
    }
}
