#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_adaptive_instance_norm2d_backward.h"

namespace ascend_kernel {

std::tuple<at::Tensor, at::Tensor, at::Tensor> adaptive_instance_norm2d_backward(
    const at::Tensor &grad_output,
    const at::Tensor &x,
    const at::Tensor &weight,
    const at::Tensor &mean,
    const at::Tensor &std) {
    TORCH_CHECK(grad_output.dim() == 4, "grad_output must be 4D (N,C,H,W)");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(x.sizes() == grad_output.sizes(), "x and grad_output must have same shape");

    auto inputDtype = x.scalar_type();
    TORCH_CHECK(inputDtype == at::kHalf || inputDtype == at::kFloat || inputDtype == at::kBFloat16,
                "Only float16, float32, bfloat16 supported, got ", inputDtype);

    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t H = x.size(2);
    int64_t W = x.size(3);
    int64_t spatialSize = H * W;
    int64_t totalNC = N * C;

    if (totalNC == 0) {
        at::Tensor gi = at::empty_like(x);
        at::Tensor gw = at::zeros({C}, at::dtype(at::kFloat).device(x.device()));
        at::Tensor gb = at::zeros({C}, at::dtype(at::kFloat).device(x.device()));
        return std::make_tuple(gi, gw, gb);
    }

    // For bf16: convert to fp32, compute, cast grad_input back
    bool isBf16 = (inputDtype == at::kBFloat16);
    auto computeDtype = isBf16 ? at::kFloat : inputDtype;

    at::Tensor goCont = isBf16 ? grad_output.to(at::kFloat).contiguous() : grad_output.contiguous();
    at::Tensor xCont = isBf16 ? x.to(at::kFloat).contiguous() : x.contiguous();
    at::Tensor wCont = isBf16 ? weight.to(at::kFloat).contiguous() : weight.contiguous();

    at::Tensor meanCont, stdCont;
    if (isBf16) {
        at::Tensor m = (mean.dim() == 4) ? mean.view({N, C}) : mean;
        at::Tensor s = (std.dim() == 4) ? std.view({N, C}) : std;
        meanCont = m.to(at::kFloat).contiguous();
        stdCont = s.to(at::kFloat).contiguous();
    } else if (mean.dim() == 4) {
        meanCont = mean.contiguous().view({N, C});
        stdCont = std.contiguous().view({N, C});
    } else {
        meanCont = mean.contiguous();
        stdCont = std.contiguous();
    }

    // ---- Get hardware parameters ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block-level tiling ----
    int64_t usedCoreNum = std::max(int64_t(1), std::min(totalNC, coreNum));
    int64_t tasksPerCore = (totalNC + usedCoreNum - 1) / usedCoreNum;

    // ---- UB-level tiling ----
    int64_t bufferCoefficient = 50;
    int64_t dtypeSize = static_cast<int64_t>(xCont.element_size());
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t tileSpatial = (maxTileElements / alignElements) * alignElements;
    if (tileSpatial < alignElements) { tileSpatial = alignElements; }
    tileSpatial = std::min(tileSpatial, spatialSize);

    // ---- Allocate outputs ----
    at::Tensor giCompute = at::empty_like(xCont);
    at::Tensor gradWeight = at::zeros({C}, at::dtype(at::kFloat).device(x.device()));
    at::Tensor gradBias = at::zeros({C}, at::dtype(at::kFloat).device(x.device()));

    // ---- Allocate workspace ----
    at::Tensor partialGW = at::zeros({usedCoreNum, C},
        at::dtype(at::kFloat).device(x.device()));
    at::Tensor partialGB = at::zeros({usedCoreNum, C},
        at::dtype(at::kFloat).device(x.device()));

    // ---- Setup dtype flag (bf16 handled via fp32 path) ----
    int64_t dtypeFlag = 0;
    if (!isBf16 && inputDtype == at::kHalf) {
        dtypeFlag = 1;
    }

    // ---- Launch kernel ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int32_t N32 = static_cast<int32_t>(N);
    int32_t C32 = static_cast<int32_t>(C);
    int32_t H32 = static_cast<int32_t>(H);
    int32_t W32 = static_cast<int32_t>(W);
    int32_t spSize32 = static_cast<int32_t>(spatialSize);
    int32_t usedCoreNum32 = static_cast<int32_t>(usedCoreNum);
    int32_t tasksPerCore32 = static_cast<int32_t>(tasksPerCore);
    int32_t tileSpatial32 = static_cast<int32_t>(tileSpatial);

    EXEC_KERNEL_CMD(adaptive_instance_norm2d_backward, blockDim,
                    goCont, xCont, wCont, meanCont, stdCont,
                    giCompute, gradWeight, gradBias,
                    partialGW, partialGB,
                    N32, C32, H32, W32,
                    spSize32, usedCoreNum32, tasksPerCore32, tileSpatial32,
                    dtypeFlag);

    // Cast grad_input back to bf16 if needed
    at::Tensor gradInput = isBf16 ? giCompute.to(at::kBFloat16) : giCompute;
    return std::make_tuple(gradInput, gradWeight, gradBias);
}

}  // namespace ascend_kernel
