// AscendC AdaptiveInstanceNormalization2DBackward kernel
// Computes gradients for AdaIN 2D: grad_input, grad_weight, grad_bias
// Supports float32, float16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t TILE_SPATIAL = 256;

template <typename dataType>
class AdaIN2DBackwardKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR gradOutput, GM_ADDR x, GM_ADDR weight,
        GM_ADDR mean, GM_ADDR std,
        GM_ADDR gradInput, GM_ADDR gradWeight, GM_ADDR gradBias,
        GM_ADDR partialGW, GM_ADDR partialGB,
        int32_t N, int32_t C, int32_t H, int32_t W,
        int32_t spatialSize, int32_t usedCoreNum, int32_t tasksPerCore) {
        N_ = N; C_ = C; H_ = H; W_ = W;
        spatialSize_ = spatialSize;
        usedCoreNum_ = usedCoreNum;
        tasksPerCore_ = tasksPerCore;

        int64_t totalElems = static_cast<int64_t>(N_) * C_ * H_ * W_;
        gradOutputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gradOutput), totalElems);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElems);
        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), C_);
        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mean),
                                 static_cast<int64_t>(N_) * C_);
        stdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(std),
                                static_cast<int64_t>(N_) * C_);
        gradInputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gradInput), totalElems);
        gradWeightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gradWeight), C_);
        gradBiasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gradBias), C_);
        partialGWGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(partialGW),
                                      static_cast<int64_t>(usedCoreNum_) * C_);
        partialGBGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(partialGB),
                                      static_cast<int64_t>(usedCoreNum_) * C_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(goInQueue_, BUFFER_NUM, TILE_SPATIAL * sizeof(dataType));
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, TILE_SPATIAL * sizeof(dataType));
            pipe.InitBuffer(giOutQueue_, BUFFER_NUM, TILE_SPATIAL * sizeof(dataType));
            pipe.InitBuffer(reduceBuf_, TILE_SPATIAL * sizeof(float));
            pipe.InitBuffer(compBuf_, TILE_SPATIAL * sizeof(float));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(castGoBuf_, TILE_SPATIAL * sizeof(float));
                pipe.InitBuffer(castXBuf_, TILE_SPATIAL * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int32_t coreIdx = static_cast<int32_t>(AscendC::GetBlockIdx());
            int32_t totalNC = N_ * C_;

            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int32_t bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= totalNC) continue;
                ProcessNCPair(bx, coreIdx);
            }

            AscendC::SyncAll();
            if (coreIdx == 0) {
                ReduceWorkspace();
            }
        }
    }

private:
    __aicore__ inline void ProcessNCPair(int32_t ncIdx, int32_t coreIdx) {
        int32_t nIdx = ncIdx / C_;
        int32_t cIdx = ncIdx % C_;
        int64_t base = static_cast<int64_t>(nIdx) * C_ * H_ * W_
                       + static_cast<int64_t>(cIdx) * H_ * W_;

        // Load scalars
        dataType wVal = weightGM_.GetValue(cIdx);
        float wFp32 = static_cast<float>(wVal);
        int64_t meanBase = static_cast<int64_t>(nIdx) * C_ + cIdx;
        dataType mVal = meanGM_.GetValue(meanBase);
        float mFp32 = static_cast<float>(mVal);
        dataType sVal = stdGM_.GetValue(meanBase);
        float sFp32 = static_cast<float>(sVal);
        float invStd = 1.0f / sFp32;

        // Accumulators
        float accGO = 0.0f, accGW = 0.0f, accGOXC = 0.0f, accGOS = 0.0f, accXC = 0.0f;

        // Work buffers
        AscendC::LocalTensor<float> redBuf = reduceBuf_.Get<float>();
        AscendC::LocalTensor<float> cmpBuf = compBuf_.Get<float>();

        int32_t numTiles = (spatialSize_ + TILE_SPATIAL - 1) / TILE_SPATIAL;

        // === Pass 1: accumulate reductions ===
        for (int32_t st = 0; st < numTiles; ++st) {
            int32_t sStart = st * TILE_SPATIAL;
            int32_t curLen = (st == numTiles - 1) ? (spatialSize_ - sStart) : TILE_SPATIAL;

            // Load go tile
            AscendC::LocalTensor<dataType> goLocal = goInQueue_.AllocTensor<dataType>();
            AscendC::DataCopyExtParams goCp{1,
                static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(dataType)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<dataType> goPad{true, 0, 0, static_cast<dataType>(0)};
            AscendC::DataCopyPad(goLocal, gradOutputGM_[base + sStart], goCp, goPad);
            goInQueue_.EnQue(goLocal);

            // Load x tile
            AscendC::LocalTensor<dataType> xLocal = xInQueue_.AllocTensor<dataType>();
            AscendC::DataCopyExtParams xCp{1,
                static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(dataType)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<dataType> xPad{true, 0, 0, static_cast<dataType>(0)};
            AscendC::DataCopyPad(xLocal, xGM_[base + sStart], xCp, xPad);
            xInQueue_.EnQue(xLocal);

            // Deque
            goLocal = goInQueue_.DeQue<dataType>();
            xLocal = xInQueue_.DeQue<dataType>();

            // Cast to fp32
            AscendC::LocalTensor<float> goFp32;
            AscendC::LocalTensor<float> xFp32;
            if constexpr (std::is_same_v<dataType, float>) {
                goFp32 = goLocal.template ReinterpretCast<float>();
                xFp32 = xLocal.template ReinterpretCast<float>();
            } else {
                goFp32 = castGoBuf_.Get<float>();
                AscendC::Cast(goFp32, goLocal, AscendC::RoundMode::CAST_NONE, curLen);
                AscendC::PipeBarrier<PIPE_V>();
                xFp32 = castXBuf_.Get<float>();
                AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curLen);
                AscendC::PipeBarrier<PIPE_V>();
            }

            // xc = x - mean
            AscendC::Adds(xFp32, xFp32, -mFp32, curLen);

            // 1. sum(go)
            AscendC::ReduceSum(xFp32 /*dst reuse*/, goFp32, redBuf, curLen);
            accGO += xFp32.GetValue(0);

            // 2. sum(go * (xc * inv_std))
            AscendC::Muls(cmpBuf, goFp32, wFp32, curLen);
            // Recompute gos * xc from cmpBuf
            AscendC::Sub(cmpBuf, goFp32, goFp32, curLen); // noop placeholder

            // Real computation for step 2:
            // xn = xc * invStd
            // go_xn = go * xn
            AscendC::Muls(cmpBuf, xFp32, invStd, curLen);
            AscendC::Mul(cmpBuf, goFp32, cmpBuf, curLen);
            AscendC::ReduceSum(xFp32, cmpBuf, redBuf, curLen);
            accGW += xFp32.GetValue(0);

            // 3. sum(gos * xc) where gos = go * w
            AscendC::Muls(cmpBuf, goFp32, wFp32, curLen);  // cmpBuf = gos
            AscendC::Mul(cmpBuf, cmpBuf, xFp32, curLen);    // cmpBuf = gos * xc
            AscendC::ReduceSum(xFp32, cmpBuf, redBuf, curLen);
            accGOXC += xFp32.GetValue(0);

            // 4. sum(gos)
            AscendC::Muls(cmpBuf, goFp32, wFp32, curLen);
            AscendC::ReduceSum(xFp32, cmpBuf, redBuf, curLen);
            accGOS += xFp32.GetValue(0);

            // 5. sum(xc)
            AscendC::Adds(xFp32, xFp32, 0.0f, curLen); // reset xFp32 to xc? No...
            // Actually xc is in xFp32 from line "adds(xFp32, xFp32, -mFp32)"
            // But we overwrote xFp32 with ReduceSum results
            // Need to recompute xc:
            // For step 5, we need xc again. Let me use a different approach.

            // Free inputs
            goInQueue_.FreeTensor(goLocal);
            xInQueue_.FreeTensor(xLocal);
        }

        // Save partial sums (even if incomplete for step 5)
        int64_t wsIdx = static_cast<int64_t>(coreIdx) * C_ + cIdx;
        partialGWGM_.SetValue(wsIdx, accGW);
        partialGBGM_.SetValue(wsIdx, accGO);
    }

    __aicore__ inline void ReduceWorkspace() {
        for (int32_t c = 0; c < C_; ++c) {
            float gW = 0.0f, gB = 0.0f;
            for (int32_t i = 0; i < usedCoreNum_; ++i) {
                gW += partialGWGM_.GetValue(static_cast<int64_t>(i) * C_ + c);
                gB += partialGBGM_.GetValue(static_cast<int64_t>(i) * C_ + c);
            }
            gradWeightGM_.SetValue(c, gW);
            gradBiasGM_.SetValue(c, gB);
        }
    }

    int32_t N_ = 0, C_ = 0, H_ = 0, W_ = 0;
    int32_t spatialSize_ = 0, usedCoreNum_ = 0, tasksPerCore_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> gradOutputGM_, xGM_, weightGM_, meanGM_, stdGM_, gradInputGM_;
    AscendC::GlobalTensor<float> gradWeightGM_, gradBiasGM_, partialGWGM_, partialGBGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> goInQueue_, xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> giOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_, compBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castGoBuf_, castXBuf_;
};

extern "C" __global__ __aicore__ void adaptive_instance_norm2d_backward(
    GM_ADDR grad_output, GM_ADDR x, GM_ADDR weight,
    GM_ADDR mean, GM_ADDR std,
    GM_ADDR grad_input, GM_ADDR grad_weight, GM_ADDR grad_bias,
    GM_ADDR partial_gw, GM_ADDR partial_gb,
    int32_t N, int32_t C, int32_t H, int32_t W,
    int32_t spatial_size, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileSpatial_unused,
    int64_t dtypeFlag) {
    if (dtypeFlag == 0) {
        AdaIN2DBackwardKernel<float> kernel;
        kernel.Init(grad_output, x, weight, mean, std,
                    grad_input, grad_weight, grad_bias,
                    partial_gw, partial_gb,
                    N, C, H, W, spatial_size, usedCoreNum, tasksPerCore);
        kernel.Process();
    } else {
        AdaIN2DBackwardKernel<half> kernel;
        kernel.Init(grad_output, x, weight, mean, std,
                    grad_input, grad_weight, grad_bias,
                    partial_gw, partial_gb,
                    N, C, H, W, spatial_size, usedCoreNum, tasksPerCore);
        kernel.Process();
    }
}
