// AscendC AdaptiveInstanceNormalization2DBackward kernel
// Computes gradients for AdaIN 2D: grad_input, grad_weight, grad_bias
// Supports float32, float16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t TILE_LEN = 256;

template <typename dataType>
class AdaIN2DBackwardKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR gradOutput, GM_ADDR x, GM_ADDR weight,
        GM_ADDR mean, GM_ADDR std,
        GM_ADDR gradInput, GM_ADDR gradWeight, GM_ADDR gradBias,
        GM_ADDR partialGW, GM_ADDR partialGB,
        int32_t N, int32_t C, int32_t H, int32_t W,
        int32_t spatialSize, int32_t usedCoreNum, int32_t tasksPerCore) {
        N_ = N; C_ = C; H_ = H; W_ = W;
        spatialSize_ = spatialSize;
        usedCoreNum_ = usedCoreNum;
        tasksPerCore_ = tasksPerCore;
        int64_t totalElems = static_cast<int64_t>(N_) * C_ * H_ * W_;
        gradOutputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gradOutput), totalElems);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElems);
        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), C_);
        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mean),
                                 static_cast<int64_t>(N_) * C_);
        stdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(std),
                                static_cast<int64_t>(N_) * C_);
        gradInputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gradInput), totalElems);
        gradWeightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gradWeight), C_);
        gradBiasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gradBias), C_);
        partialGWGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(partialGW),
                                      static_cast<int64_t>(usedCoreNum_) * C_);
        partialGBGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(partialGB),
                                      static_cast<int64_t>(usedCoreNum_) * C_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(goInQueue_, BUFFER_NUM, TILE_LEN * sizeof(dataType));
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, TILE_LEN * sizeof(dataType));
            pipe.InitBuffer(giOutQueue_, BUFFER_NUM, TILE_LEN * sizeof(dataType));
            pipe.InitBuffer(reduceBuf_, TILE_LEN * sizeof(float));
            pipe.InitBuffer(cmpBuf_, TILE_LEN * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(castGoBuf_, TILE_LEN * sizeof(float));
                pipe.InitBuffer(castXBuf_, TILE_LEN * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int32_t coreIdx = static_cast<int32_t>(AscendC::GetBlockIdx());
            int32_t totalNC = N_ * C_;
            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int32_t bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= totalNC) continue;
                ProcessNCPair(bx, coreIdx);
            }
            AscendC::SyncAll();
            if (coreIdx == 0) {
                ReduceWorkspace();
            }
        }
    }

private:
    __aicore__ inline int32_t GetCurLen(int32_t sStart) {
        return (spatialSize_ - sStart < TILE_LEN) ? (spatialSize_ - sStart) : TILE_LEN;
    }

    __aicore__ inline void LoadTile(
        AscendC::LocalTensor<dataType> &dst,
        AscendC::GlobalTensor<dataType> &gm, int64_t base, int32_t sStart, int32_t count) {
        AscendC::DataCopyExtParams cp{1,
            static_cast<uint32_t>(count)*static_cast<uint32_t>(sizeof(dataType)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<dataType> pp{true, 0, 0, static_cast<dataType>(0)};
        AscendC::DataCopyPad(dst, gm[base + sStart], cp, pp);
    }

    __aicore__ inline void StoreTile(
        AscendC::GlobalTensor<dataType> &gm, int64_t base, int32_t sStart,
        AscendC::LocalTensor<dataType> &src, int32_t count) {
        AscendC::DataCopyExtParams cp{1,
            static_cast<uint32_t>(count)*static_cast<uint32_t>(sizeof(dataType)), 0, 0, 0};
        AscendC::DataCopyPad(gm[base + sStart], src, cp);
    }

    __aicore__ inline void CastToFp32(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src, int32_t count) {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            dst = castGoBuf_.Get<float>();
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void CastToFp32Alt(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src, int32_t count) {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            dst = castXBuf_.Get<float>();
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void ProcessNCPair(int32_t ncIdx, int32_t coreIdx) {
        int32_t nIdx = ncIdx / C_;
        int32_t cIdx = ncIdx % C_;
        int64_t base = static_cast<int64_t>(nIdx) * C_ * H_ * W_
                       + static_cast<int64_t>(cIdx) * H_ * W_;

        // Scalars
        dataType wVal = weightGM_.GetValue(cIdx);
        float wFp32 = static_cast<float>(wVal);
        int64_t msBase = static_cast<int64_t>(nIdx) * C_ + cIdx;
        dataType mVal = meanGM_.GetValue(msBase);
        float mFp32 = static_cast<float>(mVal);
        dataType sVal = stdGM_.GetValue(msBase);
        float sFp32 = static_cast<float>(sVal);
        float invStd = 1.0f / sFp32;

        AscendC::LocalTensor<float> redBuf = reduceBuf_.Get<float>();
        AscendC::LocalTensor<float> cmpBuf = cmpBuf_.Get<float>();
        AscendC::LocalTensor<float> sBuf = sumBuf_.Get<float>();

        // === Pass 1: accumulate reductions ===
        float accGO = 0.0f, accGW = 0.0f, accGOXC = 0.0f, accGOS = 0.0f, accXC = 0.0f;
        int32_t nTiles = (spatialSize_ + TILE_LEN - 1) / TILE_LEN;

        for (int32_t st = 0; st < nTiles; ++st) {
            int32_t sStart = st * TILE_LEN;
            int32_t curLen = GetCurLen(sStart);

            // Load go
            AscendC::LocalTensor<dataType> goLocal = goInQueue_.AllocTensor<dataType>();
            LoadTile(goLocal, gradOutputGM_, base, sStart, curLen);
            goInQueue_.EnQue(goLocal);

            // Load x
            AscendC::LocalTensor<dataType> xLocal = xInQueue_.AllocTensor<dataType>();
            LoadTile(xLocal, xGM_, base, sStart, curLen);
            xInQueue_.EnQue(xLocal);

            // Deque
            goLocal = goInQueue_.DeQue<dataType>();
            xLocal = xInQueue_.DeQue<dataType>();

            // Cast to fp32
            AscendC::LocalTensor<float> goFp32;
            AscendC::LocalTensor<float> xFp32;
            CastToFp32(goFp32, goLocal, curLen);
            CastToFp32Alt(xFp32, xLocal, curLen);

            // xc = x - mean
            AscendC::Adds(xFp32, xFp32, -mFp32, curLen);

            // 1. ReduceSum(go)
            AscendC::ReduceSum(sBuf, goFp32, redBuf, curLen);
            accGO += sBuf.GetValue(0);

            // 2. go * (xc * inv_std) → cmpbuf, then reduce
            AscendC::Muls(cmpBuf, xFp32, invStd, curLen);
            AscendC::Mul(cmpBuf, goFp32, cmpBuf, curLen);
            AscendC::ReduceSum(sBuf, cmpBuf, redBuf, curLen);
            accGW += sBuf.GetValue(0);

            // 3. gos = go * w; then gos * xc; reduce
            AscendC::Muls(cmpBuf, goFp32, wFp32, curLen);
            AscendC::Mul(cmpBuf, cmpBuf, xFp32, curLen);
            AscendC::ReduceSum(sBuf, cmpBuf, redBuf, curLen);
            accGOXC += sBuf.GetValue(0);

            // 4. gos = go * w; reduce
            AscendC::Muls(cmpBuf, goFp32, wFp32, curLen);
            AscendC::ReduceSum(sBuf, cmpBuf, redBuf, curLen);
            accGOS += sBuf.GetValue(0);

            // 5. ReduceSum(xc)
            AscendC::ReduceSum(sBuf, xFp32, redBuf, curLen);
            accXC += sBuf.GetValue(0);

            // Free inputs (after all reads from goFp32/xFp32 are done)
            goInQueue_.FreeTensor(goLocal);
            xInQueue_.FreeTensor(xLocal);
        }

        // === Intermediate scalars ===
        float invSpSz = 1.0f / static_cast<float>(spatialSize_);
        float stdCubed = sFp32 * sFp32 * sFp32;
        float invStdCubed = 1.0f / stdCubed;
        float gradVar = accGOXC * (-0.5f) * invStdCubed;
        float xcMean = accXC * invSpSz;
        float gradMean = accGOS * (-invStd) + gradVar * (-2.0f) * xcMean;
        float coefXC = gradVar * 2.0f * invSpSz;
        float constOff = gradMean * invSpSz;

        // === Pass 2: compute grad_input ===
        for (int32_t st = 0; st < nTiles; ++st) {
            int32_t sStart = st * TILE_LEN;
            int32_t curLen = GetCurLen(sStart);

            // Load go
            AscendC::LocalTensor<dataType> goLocal = goInQueue_.AllocTensor<dataType>();
            LoadTile(goLocal, gradOutputGM_, base, sStart, curLen);
            goInQueue_.EnQue(goLocal);

            // Load x
            AscendC::LocalTensor<dataType> xLocal = xInQueue_.AllocTensor<dataType>();
            LoadTile(xLocal, xGM_, base, sStart, curLen);
            xInQueue_.EnQue(xLocal);

            // Deque
            goLocal = goInQueue_.DeQue<dataType>();
            xLocal = xInQueue_.DeQue<dataType>();

            // Cast to fp32
            AscendC::LocalTensor<float> goFp32;
            AscendC::LocalTensor<float> xFp32;
            CastToFp32(goFp32, goLocal, curLen);
            CastToFp32Alt(xFp32, xLocal, curLen);

            // xc = x - mean
            AscendC::Adds(xFp32, xFp32, -mFp32, curLen);

            // gos = go * w
            AscendC::Muls(goFp32, goFp32, wFp32, curLen);

            // gi = gos * inv_std + coef_xc * xc + const_offset
            AscendC::Muls(goFp32, goFp32, invStd, curLen);
            AscendC::Axpy(goFp32, xFp32, coefXC, curLen);
            AscendC::Adds(goFp32, goFp32, constOff, curLen);

            // Alloc output and copy BEFORE freeing inputs
            AscendC::LocalTensor<dataType> giLocal = giOutQueue_.AllocTensor<dataType>();
            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::DataCopy(giLocal, goFp32, curLen);
            } else {
                AscendC::Cast(giLocal, goFp32, AscendC::RoundMode::CAST_NONE, curLen);
            }

            // Free inputs now that goFp32/xFp32 data is in giLocal
            goInQueue_.FreeTensor(goLocal);
            xInQueue_.FreeTensor(xLocal);

            giOutQueue_.EnQue(giLocal);
            giLocal = giOutQueue_.DeQue<dataType>();
            StoreTile(gradInputGM_, base, sStart, giLocal, curLen);
            giOutQueue_.FreeTensor(giLocal);
        }

        // Store partial sums
        int64_t wsIdx = static_cast<int64_t>(coreIdx) * C_ + cIdx;
        partialGWGM_.SetValue(wsIdx, accGW);
        partialGBGM_.SetValue(wsIdx, accGO);
    }

    __aicore__ inline void ReduceWorkspace() {
        for (int32_t c = 0; c < C_; ++c) {
            float gW = 0.0f, gB = 0.0f;
            for (int32_t i = 0; i < usedCoreNum_; ++i) {
                int64_t idx = static_cast<int64_t>(i) * C_ + c;
                gW += partialGWGM_.GetValue(idx);
                gB += partialGBGM_.GetValue(idx);
            }
            gradWeightGM_.SetValue(c, gW);
            gradBiasGM_.SetValue(c, gB);
        }
    }

    int32_t N_ = 0, C_ = 0, H_ = 0, W_ = 0;
    int32_t spatialSize_ = 0, usedCoreNum_ = 0, tasksPerCore_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> gradOutputGM_, xGM_, weightGM_;
    AscendC::GlobalTensor<dataType> meanGM_, stdGM_, gradInputGM_;
    AscendC::GlobalTensor<float> gradWeightGM_, gradBiasGM_, partialGWGM_, partialGBGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> goInQueue_, xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> giOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_, cmpBuf_, sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castGoBuf_, castXBuf_;
};

