// Minimal identity kernel for debugging

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t TILE_LEN = 256;

template <typename T>
class IdentityKernel {
public:
    __aicore__ inline void Init(GM_ADDR src, GM_ADDR dst, int32_t totalElems) {
        totalElems_ = totalElems;
        srcGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(src), totalElems_);
        dstGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(dst), totalElems_);
        if ASCEND_IS_AIV {
            pipe.InitBuffer(inQueue_, BUFFER_NUM, TILE_LEN * sizeof(T));
            pipe.InitBuffer(outQueue_, BUFFER_NUM, TILE_LEN * sizeof(T));
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int32_t nTiles = (totalElems_ + TILE_LEN - 1) / TILE_LEN;
            for (int32_t st = 0; st < nTiles; ++st) {
                int32_t sStart = st * TILE_LEN;
                int32_t curLen = (totalElems_ - sStart < TILE_LEN) ? (totalElems_ - sStart) : TILE_LEN;

                // Copy in
                AscendC::LocalTensor<T> inLocal = inQueue_.AllocTensor<T>();
                AscendC::DataCopyExtParams cpIn{1,
                    static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
                AscendC::DataCopyPadExtParams<T> padIn{true, 0, 0, static_cast<T>(0)};
                AscendC::DataCopyPad(inLocal, srcGM_[sStart], cpIn, padIn);
                inQueue_.EnQue(inLocal);

                // Deque
                inLocal = inQueue_.DeQue<T>();

                // Copy out (write to output queue)
                AscendC::LocalTensor<T> outLocal = outQueue_.AllocTensor<T>();
                AscendC::DataCopy(outLocal, inLocal, curLen);
                outQueue_.EnQue(outLocal);

                // Write to GM
                outLocal = outQueue_.DeQue<T>();
                AscendC::DataCopyExtParams cpOut{1,
                    static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
                AscendC::DataCopyPad(dstGM_[sStart], outLocal, cpOut);

                // Free
                inQueue_.FreeTensor(inLocal);
                outQueue_.FreeTensor(outLocal);
            }
        }
    }

private:
    int32_t totalElems_ = 0;
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<T> srcGM_, dstGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
};

extern "C" __global__ __aicore__ void adaptive_instance_norm2d_backward(
    GM_ADDR grad_output, GM_ADDR x, GM_ADDR weight,
    GM_ADDR mean, GM_ADDR std,
    GM_ADDR grad_input, GM_ADDR grad_weight, GM_ADDR grad_bias,
    GM_ADDR partial_gw, GM_ADDR partial_gb,
    int32_t N, int32_t C, int32_t H, int32_t W,
    int32_t spatial_size, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileSpatial_unused,
    int64_t dtypeFlag) {
    int32_t totalElems = N * C * H * W;
    if (dtypeFlag == 0) {
        IdentityKernel<float> kernel;
        kernel.Init(grad_output, grad_input, totalElems);
        kernel.Process();
    } else {
        IdentityKernel<half> kernel;
        kernel.Init(grad_output, grad_input, totalElems);
        kernel.Process();
    }
}
