// Bare minimum test kernel - single TBuf, direct DataCopy, no queues

#include "kernel_operator.h"

extern "C" __global__ __aicore__ void adaptive_instance_norm2d_backward(
    GM_ADDR grad_output, GM_ADDR x, GM_ADDR weight,
    GM_ADDR mean, GM_ADDR std,
    GM_ADDR grad_input, GM_ADDR grad_weight, GM_ADDR grad_bias,
    GM_ADDR partial_gw, GM_ADDR partial_gb,
    int32_t N, int32_t C, int32_t H, int32_t W,
    int32_t spatial_size, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileSpatial_unused,
    int64_t dtypeFlag) {
    // Only operate on AIV (vector core)
    if ASCEND_IS_AIC {
        return;
    }

    int32_t totalElems = N * C * H * W;
    int32_t tileSize = 256;
    AscendC::TPipe pipe;

    if (dtypeFlag == 0) {
        // fp32 path
        typename AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
        pipe.InitBuffer(tmpBuf, tileSize * sizeof(float));

        AscendC::GlobalTensor<float> srcGM;
        AscendC::GlobalTensor<float> dstGM;
        srcGM.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(grad_output), totalElems);
        dstGM.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(grad_input), totalElems);

        AscendC::LocalTensor<float> tmp = tmpBuf.Get<float>();

        for (int32_t s = 0; s < totalElems; s += tileSize) {
            int32_t cur = (totalElems - s < tileSize) ? (totalElems - s) : tileSize;

            // Copy from GM to UB
            AscendC::DataCopyExtParams cp{1,
                static_cast<uint32_t>(cur) * static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> pp{true, 0, 0, 0.0f};
            AscendC::DataCopyPad(tmp, srcGM[s], cp, pp);
            AscendC::PipeBarrier<PIPE_MTE2>();

            // Copy UB to GM
            AscendC::DataCopyExtParams cp2{1,
                static_cast<uint32_t>(cur) * static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPad(dstGM[s], tmp, cp2);
            AscendC::PipeBarrier<PIPE_MTE2>();
        }
    } else {
        // fp16 path
        typename AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
        pipe.InitBuffer(tmpBuf, tileSize * sizeof(half));

        AscendC::GlobalTensor<half> srcGM;
        AscendC::GlobalTensor<half> dstGM;
        srcGM.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(grad_output), totalElems);
        dstGM.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(grad_input), totalElems);

        AscendC::LocalTensor<half> tmp = tmpBuf.Get<half>();

        for (int32_t s = 0; s < totalElems; s += tileSize) {
            int32_t cur = (totalElems - s < tileSize) ? (totalElems - s) : tileSize;

            AscendC::DataCopyExtParams cp{1,
                static_cast<uint32_t>(cur) * static_cast<uint32_t>(sizeof(half)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<half> pp{true, 0, 0, static_cast<half>(0)};
            AscendC::DataCopyPad(tmp, srcGM[s], cp, pp);
            AscendC::PipeBarrier<PIPE_MTE2>();

            AscendC::DataCopyExtParams cp2{1,
                static_cast<uint32_t>(cur) * static_cast<uint32_t>(sizeof(half)), 0, 0, 0};
            AscendC::DataCopyPad(dstGM[s], tmp, cp2);
            AscendC::PipeBarrier<PIPE_MTE2>();
        }
    }
}
