// Minimal identity kernel - simple class, single buffer per type

#include "kernel_operator.h"

constexpr int32_t TILE = 256;

template <typename T>
class IdentityCopy {
public:
    __aicore__ inline void Init(GM_ADDR s, GM_ADDR d, int32_t n) {
        n_ = n;
        src_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(s), n_);
        dst_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(d), n_);
        if ASCEND_IS_AIV {
            pipe.InitBuffer(buf_, TILE * sizeof(T));
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            auto loc = buf_.Get<T>();
            for (int32_t p = 0; p < n_; p += TILE) {
                int32_t c = (n_ - p < TILE) ? (n_ - p) : TILE;
                AscendC::DataCopyExtParams cp{1,
                    static_cast<uint32_t>(c) * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
                AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
                AscendC::DataCopyPad(loc, src_[p], cp, pp);
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::DataCopyExtParams cp2{1,
                    static_cast<uint32_t>(c) * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
                AscendC::DataCopyPad(dst_[p], loc, cp2);
                AscendC::PipeBarrier<PIPE_MTE2>();
            }
        }
    }
private:
    int32_t n_ = 0;
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<T> src_, dst_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> buf_;
};

