    int32_t spatial_size, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileSpatial_unused,
    int64_t dtypeFlag) {
    int32_t totalElems = N * C * H * W;
    if (dtypeFlag == 0) {
        IdentityCopy<float> k;
        k.Init(grad_output, grad_input, totalElems);
        k.Process();
    } else {
        IdentityCopy<half> k;
        k.Init(grad_output, grad_input, totalElems);
        k.Process();
    }
